import java.util.ArrayList;
import java.util.List;
import java.util.Random;


public class FieldPopulator {

	private static final double FLOWER_CREATION_PROBABILITY = 0.07;

	private static final double MOUSE_CREATION_PROBABILITY = 0.07;

	private static final double DUCK_CREATION_PROBABILITY = 0.07;

	private static final double BIRD_CREATION_PROBABILITY = 0.07;

	private static final double WOLF_CREATION_PROBABILITY = 0.03;

	private static final double BEAR_CREATION_PROBABILITY = 0.03;

	private final Random random;

	private final GraphView graphView;

	private final Climate climate;

	private final List<AnimalSpawnRule> animalSpawnRules;


	public FieldPopulator(GraphView graphView, Climate climate) {
		this.random = Randomizer.getRandom();
		this.graphView = graphView;
		this.climate = climate;
		this.animalSpawnRules = new ArrayList<>();
		registerAnimalSpawnRules();
	}


	public void populate(FieldEnvironment field, List<Animal> animals, List<Plant> plants) {
		field.clear();
		animals.clear();
		plants.clear();

		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Location location = new Location(row, col);
				plants.add(createPlant(field, location));

				Animal animal = createAnimal(field, location);
				if (animal != null) {
					animals.add(animal);
					graphView.setColor(animal.getClass(), animal.getObjectColor(climate));
				}
			}
		}
	}


	private Plant createPlant(FieldEnvironment field, Location location) {
		if (random.nextDouble() <= FLOWER_CREATION_PROBABILITY) {
			return new Flower(field, location);
		}
		return new Grass(field, location);
	}


	private Animal createAnimal(FieldEnvironment field, Location location) {
		for (AnimalSpawnRule rule : animalSpawnRules) {
			if (rule.shouldSpawn(random)) {
				return rule.createAnimal(field, location);
			}
		}
		return null;
	}


	private void registerAnimalSpawnRules() {
		animalSpawnRules.add(new AnimalSpawnRule(BIRD_CREATION_PROBABILITY) {
			@Override
			Animal createAnimal(FieldEnvironment field, Location location) {
				return new Bird(true, field, location);
			}
		});
		animalSpawnRules.add(new AnimalSpawnRule(MOUSE_CREATION_PROBABILITY) {
			@Override
			Animal createAnimal(FieldEnvironment field, Location location) {
				return new Mouse(true, field, location);
			}
		});
		animalSpawnRules.add(new AnimalSpawnRule(DUCK_CREATION_PROBABILITY) {
			@Override
			Animal createAnimal(FieldEnvironment field, Location location) {
				return new Duck(true, field, location);
			}
		});
		animalSpawnRules.add(new AnimalSpawnRule(WOLF_CREATION_PROBABILITY) {
			@Override
			Animal createAnimal(FieldEnvironment field, Location location) {
				return new Wolf(true, field, location);
			}
		});
		animalSpawnRules.add(new AnimalSpawnRule(BEAR_CREATION_PROBABILITY) {
			@Override
			Animal createAnimal(FieldEnvironment field, Location location) {
				return new Bear(true, field, location);
			}
		});
	}


	private abstract static class AnimalSpawnRule {
		private final double spawnProbability;


		private AnimalSpawnRule(double spawnProbability) {
			this.spawnProbability = spawnProbability;
		}


		private boolean shouldSpawn(Random random) {
			return random.nextDouble() <= spawnProbability;
		}


		abstract Animal createAnimal(FieldEnvironment field, Location location);
	}
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;


public class Simulator {


	private static final int DEFAULT_WIDTH = 320;

	private static final int DEFAULT_DEPTH = 200;

	private static final TimeCycle DEFAULT_TIMECYCLE = TimeCycle.DAY;

	private static final Weather DEFAULT_WEATHER = Weather.SUN;

	private static final int TIMECYCLE_LENGTH = 4;


	private List<Animal> animals;

	private List<Plant> plants;

	private FieldEnvironment field;

	private int step;

	private SimulatorView gridView;

	private GraphView graphView;

	private TimeCycle currentTimeCycle;

	private Climate climate;

	private FieldPopulator fieldPopulator;

	private int sickPercentage;


	public Simulator() {
		this(DEFAULT_DEPTH, DEFAULT_WIDTH);
		currentTimeCycle = DEFAULT_TIMECYCLE;
	}


	public Simulator(int depth, int width) {
		if (width <= 0 || depth <= 0) {
			System.out.println("The dimensions must be greater than zero.");
			System.out.println("Using default values.");
			depth = DEFAULT_DEPTH;
			width = DEFAULT_WIDTH;
		}


		animals = new ArrayList<>();

		plants = new ArrayList<>();
		field = new Field(depth, width);
		climate = new Climate(DEFAULT_WEATHER);


		gridView = new SimulatorView(depth, width);


		graphView = new GraphView(1000, 500, 500);
		fieldPopulator = new FieldPopulator(graphView, climate);


		reset();
	}


	public void runLongSimulation() {
		simulate(4000);
	}


	public void simulate(int numSteps) {
		for (int step = 1; step <= numSteps && gridView.isViable(field); step++) {
			simulateOneStep();
			delay(60);
		}
	}


	public void simulateOneStep() {
		step++;
		climate.updateClimate(step);


		for (Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
			Plant plant = it.next();
			plant.increaseStage(climate);
		}


		List<Animal> newAnimals = new ArrayList<>();

		for (Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
			Animal animal = it.next();
			animal.act(newAnimals, currentTimeCycle);
			if (!animal.isAlive()) {
				it.remove();
			}
		}


		animals.addAll(newAnimals);


		if (step % TIMECYCLE_LENGTH == 0) {
			currentTimeCycle = currentTimeCycle.toggle();
		}

		updateViews();
	}


	public void reset() {
		step = 0;
		fieldPopulator.populate(field, animals, plants);
		currentTimeCycle = DEFAULT_TIMECYCLE;
		climate.setCurrentWeather(Weather.SUN);

		sickPercentage = 0;
		graphView.reset();
		updateViews();
	}


	private void updateViews() {
		sickPercentage = calculateSickPercentage();
		gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
		graphView.showStatus(step, field);
	}


	private int calculateSickPercentage() {
		if (animals.isEmpty()) {
			return 0;
		}

		int sickAnimals = 0;
		for (Animal animal : animals) {
			if (animal.isSick()) {
				sickAnimals++;
			}
		}
		return (sickAnimals * 100) / animals.size();
	}


	private void delay(int millisec) {
		try {
			Thread.sleep(millisec);
		} catch (InterruptedException ie) {

		}
	}
}

import java.util.Random;


public class Climate {

	private static final int SEASON_LENGTH = 16;

	private static final Random rand = Randomizer.getRandom();

	private Weather currentWeather;

	private Season currentSeason;

	private int humidity;


	public Climate(Weather currentWeather) {
		this.currentWeather = currentWeather;
		currentSeason = Season.SPRING;
	}


	public void updateClimate(int step) {
		updateSeason(step);


		int humidityIncrease = rand.nextInt((20 - 10) + 1) + 10;

		if (humidity < 80 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
			humidity += humidityIncrease;
		} else if (humidity < 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
			humidity += humidityIncrease;
			currentWeather = Weather.CLOUD;
		} else if (humidity > 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD) && currentSeason != Season.WINTER) {
			currentWeather = Weather.RAIN;
		} else if (humidity > 80 && currentWeather == Weather.RAIN) {
			humidity -= humidityIncrease;
		} else {
			humidity = 0;
			currentWeather = Weather.SUN;
		}
	}


	private void updateSeason(int step) {
		switch ((step / SEASON_LENGTH) % 4) {
			case 0:
				currentSeason = Season.SPRING;
				break;
			case 1:
				currentSeason = Season.SUMMER;
				break;
			case 2:
				currentSeason = Season.AUTUMN;
				break;
			case 3:
				currentSeason = Season.WINTER;
				break;
		}
	}


	public Weather getCurrentWeather() {
		return currentWeather;
	}


	public void setCurrentWeather(Weather currentWeather) {
		this.currentWeather = currentWeather;
	}


	public Season getCurrentSeason() {
		return currentSeason;
	}


	public int getHumidity() {
		return humidity;
	}

}

import java.util.Random;


public class Randomizer {

	private static final int SEED = 1111;

	private static final Random rand = new Random(SEED);

	private static final boolean useShared = true;


	public Randomizer() {
	}


	public static Random getRandom() {
		if (useShared) {
			return rand;
		} else {
			return new Random();
		}
	}


	public static void reset() {
		if (useShared) {
			rand.setSeed(SEED);
		}
	}
}

import java.util.Iterator;
import java.util.List;
import java.util.Random;


public abstract class Animal extends Entity {


	private static final Random rand = Randomizer.getRandom();

	private final AnimalSpecies species;

	private boolean alive;

	private int age;

	private final Gender gender;

	private int foodLevel;

	private boolean sick;

	private int sickStep;


	public Animal(FieldEnvironment field, Location location, AnimalSpecies species) {
		super(field, location);
		this.species = species;
		alive = true;
		gender = Gender.randomGender();
		sick = false;
	}


	abstract protected void normalAct(List<Animal> newAnimals);


	public void act(List<Animal> newAnimals, TimeCycle time) {
		incrementAge();
		incrementHunger();
		battleSickness();
		if (isAlive() && isActiveDuring(time)) {
			normalAct(newAnimals);
		}
	}


	protected void incrementAge() {
		age++;
		if (age > getMaxAge()) {
			setDead();
		}
	}


	private boolean canBreed() {
		if (age < getBreedingAge()) {
			return false;
		}

		FieldEnvironment field = getField();
		List<Location> adjacent = field.getAdjacentAnimalLocations(getLocation());
		Iterator<Location> it = adjacent.iterator();
		while (it.hasNext()) {
			Location where = it.next();
			Animal animalNear = field.getAnimalAt(where);
			if (animalNear != null
					&& animalNear.getClass().equals(getClass())
					&& getGender() != animalNear.getGender()) {
				return true;
			}
		}
		return false;
	}


	private int breed() {
		int births = 0;
		if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
			births = rand.nextInt(getMaxLitterSize()) + 1;
		}
		return births;
	}


	protected void giveBirth(List<Animal> newAnimals) {


		if (this.getGender() == Gender.FEMALE) {
			FieldEnvironment field = getField();
			List<Location> free = field.getFreeAnimalAdjacentLocations(getLocation());
			int births = breed();
			for (int b = 0; b < births && free.size() > 0; b++) {
				Location loc = free.remove(0);
				Animal young = species.createAnimal(false, field, loc);
				newAnimals.add(young);
			}
		}
	}


	protected boolean isAlive() {
		return alive;
	}


	protected void setDead() {
		alive = false;
		if (getLocation() != null) {
			clearFieldLocation(getField(), getLocation());
			setLocationNull();
			setFieldNull();
		}
	}


	protected void becomeSick() {
		if (!isSick()) {
			int randomNumber = rand.nextInt(getSickProbability());
			if (randomNumber == 1) {
				toggleSick();
			}
		}
	}


	protected void notSick() {
		if (isSick()) {
			int randomNumber = rand.nextInt(getRecoverProbability());
			if (randomNumber == 1) {
				toggleSick();
				sickStep = 0;
			}
		}
	}


	protected void battleSickness() {
		if (sick) {
			if (sickStep >= species.getMaxSickStep()) {
				setDead();
				return;
			}
			sickStep++;
			FieldEnvironment field = getField();
			if (field != null) {
				List<Location> adjacent = field.getAdjacentAnimalLocations(getLocation());
				Iterator<Location> it = adjacent.iterator();
				while (it.hasNext()) {
					Location where = it.next();
					Animal nearAnimal = field.getAnimalAt(where);
					if (nearAnimal != null && nearAnimal.getClass().equals(getClass())) {
						nearAnimal.becomeSick();
					}
				}
				this.notSick();
			}
		} else {
			becomeSick();
		}
	}


	protected void incrementHunger() {
		foodLevel--;
		if (foodLevel <= 0) {
			setDead();
		}
	}


	protected void moveTo(Location newLocation) {
		if (newLocation != null) {
			setLocation(newLocation);
		} else {
			setDead();
		}
	}


	protected void toggleSick() {
		sick = !sick;

	}


	protected int getSickProbability() {
		return species.getSickProbability();
	}


	protected int getRecoverProbability() {
		return species.getRecoverProbability();
	}


	protected Gender getGender() {
		return gender;
	}


	protected int getFoodChainLevel() {
		return species.getFoodChainLevel();
	}


	protected int getFoodValue() {
		return species.getFoodValue();
	}


	protected boolean isNocturnal() {
		return species.isNocturnal();
	}


	protected boolean isSick() {
		return sick;
	}


	@Override
	protected void placeInField(FieldEnvironment field, Location location) {
		field.placeAnimal(this, location);
	}


	@Override
	protected void clearFieldLocation(FieldEnvironment field, Location location) {
		field.clearAnimalAt(location);
	}


	protected void setAge(int age) {
		this.age = age;
	}


	public int getFoodLevel() {
		return foodLevel;
	}


	public void setFoodLevel(int foodLevel) {
		this.foodLevel = foodLevel;
	}


	public int getSickStep() {
		return sickStep;
	}


	public void setSickStep(int inputValue) {
		this.sickStep = inputValue;
	}


	protected AnimalSpecies getSpecies() {
		return species;
	}


	private boolean isActiveDuring(TimeCycle time) {
		return time == TimeCycle.NIGHT ? isNocturnal() : !isNocturnal();
	}


	private int getBreedingAge() {
		return species.getBreedingAge();
	}


	private int getMaxAge() {
		return species.getMaxAge();
	}


	private double getBreedingProbability() {
		return species.getBreedingProbability();
	}


	private int getMaxLitterSize() {
		return species.getMaxLitterSize();
	}
}

import java.util.HashMap;
import java.util.Map;


public class FieldStats {

	private final Map<Class<?>, Counter> counters;

	private boolean countsValid;


	public FieldStats() {
		counters = new HashMap<>();
		countsValid = true;
	}


	public String getPopulationDetails(FieldEnvironment field) {
		StringBuilder buffer = new StringBuilder();
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class<?> key : counters.keySet()) {
			Counter info = counters.get(key);
			buffer.append(info.getName());
			buffer.append(": ");
			buffer.append(info.getCount());
			buffer.append(' ');
		}
		return buffer.toString();
	}


	public void reset() {
		countsValid = false;
		for (Class<?> key : counters.keySet()) {
			Counter count = counters.get(key);
			count.reset();
		}
	}


	public void incrementCount(Class<?> animalClass) {
		Counter count = counters.get(animalClass);
		if (count == null) {
			count = new Counter(animalClass.getName());
			counters.put(animalClass, count);
		}
		count.increment();
	}


	public void countFinished() {
		countsValid = true;
	}


	public boolean isViable(FieldEnvironment field) {

		int nonZero = 0;
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class<?> key : counters.keySet()) {
			Counter info = counters.get(key);
			if (info.getCount() > 0) {
				nonZero++;
			}
		}
		return nonZero > 1;
	}


	private void generateCounts(FieldEnvironment field) {
		reset();
		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Animal animal = field.getAnimalAt(row, col);
				if (animal != null) {
					incrementCount(animal.getClass());
				}
			}
		}
		countsValid = true;
	}


	public int getPopulationCount(FieldEnvironment field, Class<?> key) {
		if (!countsValid) {
			generateCounts(field);
		}
		int total = 0;
		for (Class<?> currentKey : counters.keySet()) {
			if (currentKey.equals(key)) {
				Counter counter = counters.get(currentKey);
				total = total + counter.getCount();
			}
		}
		return total;
	}
}

import java.util.Random;


public enum Gender {
	FEMALE,
	MALE;


	public static Gender randomGender() {
		Random rand = Randomizer.getRandom();
		if (rand.nextInt(2) == 0) {
			return Gender.FEMALE;
		}
		return Gender.MALE;
	}
}

import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;


public class GraphView extends JFrame {
	private static final Color LIGHT_GRAY = new Color(0, 0, 0, 40);

	private static JFrame frame;
	private static GraphPanel graph;
	private static JLabel stepLabel;
	private static JLabel countLabel;


	private Set<Class<?>> classes;

	private Map<Class<?>, Color> colors;

	private FieldStats stats;


	public GraphView(int width, int height, int startMax) {
		stats = new FieldStats();
		classes = new HashSet<>();
		colors = new HashMap<>();

		if (frame == null) {
			frame = makeFrame(width, height, startMax);
		} else {
			graph.newRun();
		}

	}


	public void setColor(Class<?> animalClass, Color color) {
		colors.put(animalClass, color);
		classes = colors.keySet();
	}


	public void showStatus(int step, FieldEnvironment field) {
		graph.update(step, field, stats);
	}


	public boolean isViable(FieldEnvironment field) {
		return stats.isViable(field);
	}


	public void reset() {
		stats.reset();
		graph.newRun();
	}


	private JFrame makeFrame(int width, int height, int startMax) {
		JFrame frame = new JFrame("Graph View");
		frame.setDefaultCloseOperation(JFrame.HIDE_ON_CLOSE);

		Container contentPane = frame.getContentPane();

		graph = new GraphPanel(width, height, startMax);
		contentPane.add(graph, BorderLayout.CENTER);

		JPanel bottom = new JPanel();
		bottom.add(new JLabel("Step:"));
		stepLabel = new JLabel("");
		bottom.add(stepLabel);
		countLabel = new JLabel(" ");
		bottom.add(countLabel);
		contentPane.add(bottom, BorderLayout.SOUTH);

		frame.pack();
		frame.setLocation(20, 600);

		frame.setVisible(true);

		return frame;
	}


	class GraphPanel extends JComponent {
		private static final double SCALE_FACTOR = 0.8;


		private BufferedImage graphImage;
		private int[] lastVal;
		private int yMax;


		public GraphPanel(int width, int height, int startMax) {
			graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
			clearImage();
			lastVal = new int[classes.size()];
			Arrays.fill(lastVal, height);
			yMax = startMax;
		}


		public void newRun() {
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			Graphics g = graphImage.getGraphics();
			g.copyArea(4, 0, width - 4, height, -4, 0);
			g.setColor(Color.BLACK);
			g.drawLine(width - 4, 0, width - 4, height);
			g.drawLine(width - 2, 0, width - 2, height);
			lastVal = new int[classes.size()];
			Arrays.fill(lastVal, height);
			repaint();
		}


		public void update(int step, FieldEnvironment field, FieldStats stats) {

			Graphics g = graphImage.getGraphics();

			int height = graphImage.getHeight();
			int width = graphImage.getWidth();


			g.copyArea(1, 0, width - 1, height, -1, 0);

			stats.reset();

			int i = 0;
			for (Iterator<Class<?>> it = classes.iterator(); it.hasNext(); i++) {
				Class<?> nextClass = it.next();
				int count = stats.getPopulationCount(field, nextClass);


				int y = height - ((height * count) / yMax) - 1;
				while (y < 0) {
					scaleDown();
					y = height - ((height * count) / yMax) - 1;
				}
				g.setColor(LIGHT_GRAY);
				g.drawLine(width - 2, y, width - 2, height);
				g.setColor(colors.get(nextClass));
				g.drawLine(width - 3, lastVal[i], width - 2, y);
				lastVal[i] = y;
			}

			repaint();

			stepLabel.setText("" + step);
			countLabel.setText(stats.getPopulationDetails(field));

		}


		public void scaleDown() {
			Graphics g = graphImage.getGraphics();
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
					BufferedImage.TYPE_INT_RGB);
			Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();

			gtmp.scale(1.0, SCALE_FACTOR);
			gtmp.drawImage(graphImage, 0, 0, null);

			int oldTop = (int) (height * (1.0 - SCALE_FACTOR));

			g.setColor(Color.WHITE);
			g.fillRect(0, 0, width, oldTop);
			g.drawImage(tmpImage, 0, oldTop, null);

			yMax = (int) (yMax / SCALE_FACTOR);

			for (int i = 0; i < lastVal.length; i++) {
				lastVal[i] = oldTop + (int) (lastVal[i] * SCALE_FACTOR);
			}

			repaint();
		}


		final public void clearImage() {
			Graphics g = graphImage.getGraphics();
			g.setColor(Color.WHITE);
			g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
			repaint();
		}


		public Dimension getPreferredSize() {
			return new Dimension(graphImage.getWidth(), graphImage.getHeight());
		}


		public boolean isOpaque() {
			return true;
		}


		public void paintComponent(Graphics g) {
			if (graphImage != null) {
				g.drawImage(graphImage, 0, 0, null);
			}
		}
	}
}

import java.awt.*;
import java.util.Random;


public class Grass extends Plant {

	private static final Random rand = Randomizer.getRandom();


	public Grass(FieldEnvironment field, Location location) {
		super(field, location);


		if (rand.nextDouble() <= 0.5) {
			setMaxStage(3);
		} else if (rand.nextDouble() <= 0.3) {
			setMaxStage(2);
		} else {
			setMaxStage(1);
		}
		setStage(getMaxStage());
	}


	protected void increaseStage(Climate climate) {
		super.increaseStage(climate);
		if (climate.getCurrentSeason() == Season.SPRING && getStage() > 2) {
			setStage(2);
		} else if (climate.getCurrentSeason() == Season.SUMMER && getStage() > 3) {
			setStage(3);
		} else if (climate.getCurrentSeason() == Season.AUTUMN && getStage() > 2) {
			setStage(2);
		} else if (climate.getCurrentSeason() == Season.WINTER && getStage() > 1) {
			setStage(1);
		}
	}


	protected Color getObjectColor(Climate climate) {
		switch (climate.getCurrentSeason()) {
			case SPRING:
				if (getStage() == 2) {
					return new Color(34, 140, 61);
				} else if (getStage() == 1) {
					return new Color(68, 201, 104);
				} else {
					return new Color(131, 101, 57);
				}
			case SUMMER:
				if (getStage() == 3) {
					return new Color(11, 102, 35);
				} else if (getStage() == 2) {
					return new Color(34, 140, 61);
				} else if (getStage() == 1) {
					return new Color(68, 201, 104);
				} else {
					return new Color(131, 101, 57);
				}
			case AUTUMN:
				if (getStage() == 2) {
					return new Color(68, 201, 104);
				} else if (getStage() == 1) {
					return new Color(154, 140, 84);
				} else {
					return new Color(131, 101, 57);
				}
			case WINTER:
				if (getStage() == 1) {
					return new Color(214, 233, 202);
				} else {
					return new Color(255, 250, 250);
				}
			default:
				return new Color(0, 0, 0);
		}
	}
}

