import java.util.Random;


public abstract class Plant extends Entity {


	private static final Random rand = Randomizer.getRandom();

	private int stage;

	private int maxStage;


	public Plant(FieldEnvironment field, Location location) {
		super(field, location);
	}


	protected void increaseStage(Climate climate) {
		if (stage < getMaxStage()) {
			if (climate.getCurrentWeather() == Weather.RAIN) {
				if (rand.nextDouble() <= 0.33) {
					stage++;
				}
			}
		}
	}


	protected int getMaxStage() {
		return maxStage;
	}


	protected void setMaxStage(int maxStage) {
		this.maxStage = maxStage;
	}


	protected void reduceStage() {
		stage--;
	}


	protected boolean canEat() {
		return stage > 0;
	}


	protected int getStage() {
		return stage;
	}


	protected void setStage(int stage) {
		this.stage = stage;
	}


	@Override
	protected void placeInField(FieldEnvironment field, Location location) {
		field.placePlant(this, location);
	}


	@Override
	protected void clearFieldLocation(FieldEnvironment field, Location location) {
		field.clearPlantAt(location);
	}
}

import java.util.List;
import java.util.Random;


public abstract class Prey extends Animal {

	private static final Random rand = Randomizer.getRandom();


	public Prey(boolean randomAge, FieldEnvironment field, Location location, AnimalSpecies species) {
		super(field, location, species);
		setAge(0);
		setFoodLevel(6);
		if (randomAge) {
			setAge(rand.nextInt(getSpecies().getMaxAge()));
		}
	}


	protected void normalAct(List<Animal> newAnimals) {
		findFood();
		giveBirth(newAnimals);
		moveTo(getField().freeAnimalAdjacentLocation(getLocation()));
	}


	private void findFood() {
		FieldEnvironment field = getField();
		Location where = getLocation();
		Plant nearPlant = field.getPlantAt(where);

		if (nearPlant != null && nearPlant.canEat()) {
			nearPlant.reduceStage();
			setFoodLevel(8);
		}
	}
}

import java.util.Iterator;
import java.util.List;
import java.util.Random;


public abstract class Predator extends Animal {


	private static final Random rand = Randomizer.getRandom();

	public Predator(boolean randomAge, FieldEnvironment field, Location location, AnimalSpecies species) {
		super(field, location, species);
		if (randomAge) {
			setAge(rand.nextInt(getSpecies().getMaxAge()));
			setFoodLevel(rand.nextInt(5));
		} else {
			setAge(0);
			setFoodLevel(6);
		}
	}


	protected void normalAct(List<Animal> newAnimals) {
		giveBirth(newAnimals);

		Location newLocation = findFood();
		if (isAlive()) {
			if (newLocation == null) {
				newLocation = getField().freeAnimalAdjacentLocation(getLocation());
			}
			moveTo(newLocation);
		}
	}


	private Location findFood() {
		FieldEnvironment field = getField();
		List<Location> adjacent = field.getAdjacentAnimalLocations(getLocation());
		Iterator<Location> it = adjacent.iterator();
		while (it.hasNext()) {
			Location where = it.next();
			Animal nearAnimal = field.getAnimalAt(where);
			if (nearAnimal != null) {
				if (nearAnimal.getFoodChainLevel() < this.getFoodChainLevel()) {
					if (nearAnimal.isAlive()) {
						nearAnimal.setDead();
						setFoodLevel(nearAnimal.getFoodValue() + getSpecies().getAdditionalFoodValue());
						return where;
					}
				}

				if (nearAnimal.getFoodChainLevel() == this.getFoodChainLevel()) {
					if (nearAnimal.isAlive() && getSpecies().isCannibal()) {
						if (getFoodLevel() < 2 && nearAnimal.getClass().equals(this.getClass())) {
							nearAnimal.setDead();
							setFoodLevel(nearAnimal.getFoodValue() + getSpecies().getAdditionalFoodValue());
							return where;
						}
					}
				}
			}
		}
		return null;
	}
}

