import javax.swing.*;
import java.awt.*;


public class SimulatorView extends JFrame {

	private static final Color EMPTY_COLOR = Color.white;

	private final String STEP_PREFIX = "Step: ";
	private final String POPULATION_PREFIX = "Population: ";
	private final String DAYCYCLE_PREFIX = "Day cycle: ";
	private final String CLIMATE_PREFIX = "Season: ";
	private final String WEATHER_PREFIX = "Weather: ";
	private final String INFECTION_PREFIX = "Infection: ";
	private final String HUMIDITY_PREFIX = "Humidity: ";
	private JLabel stepLabel, populationLabel, dayCycleLabel, climateLabel, infectLabel, weatherLabel, humidityLabel;
	private FieldView fieldView;

	private FieldStats stats;


	public SimulatorView(int height, int width) {
		stats = new FieldStats();

		setTitle("Predator-Prey Simulation");
		stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
		populationLabel = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
		dayCycleLabel = new JLabel(DAYCYCLE_PREFIX, JLabel.CENTER);
		climateLabel = new JLabel(CLIMATE_PREFIX, JLabel.CENTER);
		weatherLabel = new JLabel(WEATHER_PREFIX, JLabel.CENTER);
		infectLabel = new JLabel(INFECTION_PREFIX, JLabel.CENTER);
		humidityLabel = new JLabel(HUMIDITY_PREFIX, JLabel.CENTER);

		setLocation(100, 50);

		fieldView = new FieldView(height, width);

		Container contents = getContentPane();

		JPanel infoPane = new JPanel(new FlowLayout());
		JPanel detailPane = new JPanel(new BorderLayout());

		infoPane.add(stepLabel);
		infoPane.add(dayCycleLabel);
		infoPane.add(climateLabel);
		infoPane.add(weatherLabel);
		infoPane.add(humidityLabel);
		infoPane.add(infectLabel);
		contents.add(infoPane, BorderLayout.NORTH);
		contents.add(fieldView, BorderLayout.CENTER);
		contents.add(detailPane, BorderLayout.SOUTH);
		detailPane.add(populationLabel, BorderLayout.CENTER);

		pack();
		setVisible(true);
	}


	public void showStatus(int step, TimeCycle currentTimeCycle, FieldEnvironment field, Climate climate, int infect) {
		if (!isVisible()) {
			setVisible(true);
		}

		stepLabel.setText(STEP_PREFIX + step);
		dayCycleLabel.setText(DAYCYCLE_PREFIX + currentTimeCycle + " ");
		this.climateLabel.setText(CLIMATE_PREFIX + climate.getCurrentSeason());
		this.weatherLabel.setText(WEATHER_PREFIX + climate.getCurrentWeather());
		this.infectLabel.setText(INFECTION_PREFIX + infect + "%");
		this.humidityLabel.setText(HUMIDITY_PREFIX + climate.getHumidity() + "%");
		stats.reset();

		fieldView.preparePaint();


		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Animal animal = field.getAnimalAt(row, col);
				Plant plant = field.getPlantAt(row, col);
				if (animal != null) {
					stats.incrementCount(animal.getClass());
					fieldView.drawMark(col, row, animal.getObjectColor(climate));
				} else if (plant != null) {
					fieldView.drawMark(col, row, plant.getObjectColor(climate));
				} else {
					fieldView.drawMark(col, row, EMPTY_COLOR);
				}
			}
		}
		stats.countFinished();

		populationLabel.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
		fieldView.repaint();
	}


	public boolean isViable(FieldEnvironment field) {
		return stats.isViable(field);
	}


	private class FieldView extends JPanel {
		private final int GRID_VIEW_SCALING_FACTOR = 5;
		Dimension size;
		private int gridWidth, gridHeight;
		private int xScale, yScale;
		private Graphics g;
		private Image fieldImage;


		public FieldView(int height, int width) {
			gridHeight = height;
			gridWidth = width;
			size = new Dimension(0, 0);
		}


		public Dimension getPreferredSize() {
			return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
					gridHeight * GRID_VIEW_SCALING_FACTOR);
		}


		public void preparePaint() {
			if (!size.equals(getSize())) {
				size = getSize();
				fieldImage = fieldView.createImage(size.width, size.height);
				g = fieldImage.getGraphics();

				xScale = size.width / gridWidth;
				if (xScale < 1) {
					xScale = GRID_VIEW_SCALING_FACTOR;
				}
				yScale = size.height / gridHeight;
				if (yScale < 1) {
					yScale = GRID_VIEW_SCALING_FACTOR;
				}
			}
		}


		public void drawMark(int x, int y, Color color) {
			g.setColor(color);
			g.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
			g.drawRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
		}


		public void paintComponent(Graphics g) {
			if (fieldImage != null) {
				Dimension currentSize = getSize();
				if (size.equals(currentSize)) {
					g.drawImage(fieldImage, 0, 0, null);
				} else {

					g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
				}
			}
		}
	}
}

import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.IntStream;


public class GraphView extends JFrame {
	private static final Color LIGHT_GRAY = new Color(0, 0, 0, 40);

	private static JFrame frame;
	private static GraphPanel graph;
	private static JLabel stepLabel;
	private static JLabel countLabel;

	private final Map<Class<?>, Color> colors;

	private final FieldStats stats;


	public GraphView(int width, int height, int startMax) {
		stats = new FieldStats();
		colors = new LinkedHashMap<>();

		if (frame == null) {
			frame = makeFrame(width, height, startMax);
		} else {
			graph.newRun();
		}

	}


	public void setColor(Class<?> animalClass, Color color) {
		colors.put(animalClass, color);
	}


	public void showStatus(int step, FieldEnvironment field) {
		graph.update(step, field, stats);
	}


	public boolean isViable(FieldEnvironment field) {
		return stats.isViable(field);
	}


	public void reset() {
		stats.reset();
		graph.newRun();
	}


	private JFrame makeFrame(int width, int height, int startMax) {
		JFrame frame = new JFrame("Graph View");
		frame.setDefaultCloseOperation(JFrame.HIDE_ON_CLOSE);

		Container contentPane = frame.getContentPane();

		graph = new GraphPanel(width, height, startMax);
		contentPane.add(graph, BorderLayout.CENTER);

		JPanel bottom = new JPanel();
		bottom.add(new JLabel("Step:"));
		stepLabel = new JLabel("");
		bottom.add(stepLabel);
		countLabel = new JLabel(" ");
		bottom.add(countLabel);
		contentPane.add(bottom, BorderLayout.SOUTH);

		frame.pack();
		frame.setLocation(20, 600);

		frame.setVisible(true);

		return frame;
	}


	class GraphPanel extends JComponent {
		private static final double SCALE_FACTOR = 0.8;


		private BufferedImage graphImage;
		private int[] lastVal;
		private int yMax;


		public GraphPanel(int width, int height, int startMax) {
			graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
			clearImage();
			lastVal = new int[getTrackedClassCount()];
			Arrays.fill(lastVal, height);
			yMax = startMax;
		}


		public void newRun() {
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			Graphics g = graphImage.getGraphics();
			g.copyArea(4, 0, width - 4, height, -4, 0);
			g.setColor(Color.BLACK);
			g.drawLine(width - 4, 0, width - 4, height);
			g.drawLine(width - 2, 0, width - 2, height);
			lastVal = new int[getTrackedClassCount()];
			Arrays.fill(lastVal, height);
			repaint();
		}


		public void update(int step, FieldEnvironment field, FieldStats stats) {

			Graphics g = graphImage.getGraphics();

			int height = graphImage.getHeight();
			int width = graphImage.getWidth();


			g.copyArea(1, 0, width - 1, height, -1, 0);

			stats.reset();

			List<Class<?>> trackedClasses = new ArrayList<>(colors.keySet());
			IntStream.range(0, trackedClasses.size())
					.forEach(index -> updateGraphLine(g, field, stats, trackedClasses.get(index), index, width, height));

			repaint();

			stepLabel.setText("" + step);
			countLabel.setText(stats.getPopulationDetails(field));

		}


		public void scaleDown() {
			Graphics g = graphImage.getGraphics();
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
					BufferedImage.TYPE_INT_RGB);
			Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();

			gtmp.scale(1.0, SCALE_FACTOR);
			gtmp.drawImage(graphImage, 0, 0, null);

			int oldTop = (int) (height * (1.0 - SCALE_FACTOR));

			g.setColor(Color.WHITE);
			g.fillRect(0, 0, width, oldTop);
			g.drawImage(tmpImage, 0, oldTop, null);

			yMax = (int) (yMax / SCALE_FACTOR);

			IntStream.range(0, lastVal.length)
					.forEach(index -> lastVal[index] = oldTop + (int) (lastVal[index] * SCALE_FACTOR));

			repaint();
		}


		final public void clearImage() {
			Graphics g = graphImage.getGraphics();
			g.setColor(Color.WHITE);
			g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
			repaint();
		}


		public Dimension getPreferredSize() {
			return new Dimension(graphImage.getWidth(), graphImage.getHeight());
		}


		public boolean isOpaque() {
			return true;
		}


		public void paintComponent(Graphics g) {
			if (graphImage != null) {
				g.drawImage(graphImage, 0, 0, null);
			}
		}
	}


	private int getTrackedClassCount() {
		return colors.size();
	}


	private void updateGraphLine(Graphics graphics, FieldEnvironment field, FieldStats stats, Class<?> animalClass,
			int index, int width, int height) {
		int count = stats.getPopulationCount(field, animalClass);
		int y = scalePopulationToY(height, count);
		graphics.setColor(LIGHT_GRAY);
		graphics.drawLine(width - 2, y, width - 2, height);
		graphics.setColor(colors.get(animalClass));
		graphics.drawLine(width - 3, lastVal[index], width - 2, y);
		lastVal[index] = y;
	}


	private int scalePopulationToY(int height, int count) {
		int y = height - ((height * count) / graph.yMax) - 1;
		while (y < 0) {
			graph.scaleDown();
			y = height - ((height * count) / graph.yMax) - 1;
		}
		return y;
	}
