54		public <T> void shuffle(List<T> values) {
55			for (int index = values.size() - 1; index > 0; index--) {
56				int swapIndex = random.nextInt(index + 1);
57				T currentValue = values.get(index);
58				values.set(index, values.get(swapIndex));
59				values.set(swapIndex, currentValue);
60			}
61		}
