 85		class GraphPanel extends JComponent {
 86			private static final double SCALE_FACTOR = 0.8;
 87	
 88	
 89			private BufferedImage graphImage;
 90			private int[] lastVal;
 91			private int yMax;
 92	
 93	
 94			public GraphPanel(int width, int height, int startMax) {
 95				graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
 96				clearImage();
 97				lastVal = new int[getTrackedClassCount()];
 98				Arrays.fill(lastVal, height);
 99				yMax = startMax;
100			}
101	
102	
103			public void newRun() {
104				int height = graphImage.getHeight();
105				int width = graphImage.getWidth();
106	
107				Graphics g = graphImage.getGraphics();
108				g.copyArea(4, 0, width - 4, height, -4, 0);
109				g.setColor(Color.BLACK);
110				g.drawLine(width - 4, 0, width - 4, height);
111				g.drawLine(width - 2, 0, width - 2, height);
112				lastVal = new int[getTrackedClassCount()];
113				Arrays.fill(lastVal, height);
114				repaint();
115			}
116	
117	
118			public void update(int step, FieldEnvironment field, FieldStats stats) {
119	
120				Graphics g = graphImage.getGraphics();
121	
122				int height = graphImage.getHeight();
123				int width = graphImage.getWidth();
124	
125	
126				g.copyArea(1, 0, width - 1, height, -1, 0);
127	
128				stats.reset();
129	
130				List<Class<?>> trackedClasses = new ArrayList<>(colors.keySet());
131				IntStream.range(0, trackedClasses.size())
132						.forEach(index -> updateGraphLine(g, field, stats, trackedClasses.get(index), index, width, height));
133	
134				repaint();
135	
136				stepLabel.setText("" + step);
137				countLabel.setText(stats.getPopulationDetails(field));
138	
139			}
140	
141	
142			public void scaleDown() {
143				Graphics g = graphImage.getGraphics();
144				int height = graphImage.getHeight();
145				int width = graphImage.getWidth();
146	
147				BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
148						BufferedImage.TYPE_INT_RGB);
149				Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();
150	
151				gtmp.scale(1.0, SCALE_FACTOR);
152				gtmp.drawImage(graphImage, 0, 0, null);
153	
154				int oldTop = (int) (height * (1.0 - SCALE_FACTOR));
155	
156				g.setColor(Color.WHITE);
157				g.fillRect(0, 0, width, oldTop);
158				g.drawImage(tmpImage, 0, oldTop, null);
159	
160				yMax = (int) (yMax / SCALE_FACTOR);
161	
162				IntStream.range(0, lastVal.length)
163						.forEach(index -> lastVal[index] = oldTop + (int) (lastVal[index] * SCALE_FACTOR));
164	
165				repaint();
166			}
167	
168	
169			final public void clearImage() {
170				Graphics g = graphImage.getGraphics();
171				g.setColor(Color.WHITE);
172				g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
173				repaint();
174			}
175	
176	
177			public Dimension getPreferredSize() {
178				return new Dimension(graphImage.getWidth(), graphImage.getHeight());
179			}
180	
181	
182			public boolean isOpaque() {
183				return true;
184			}
185	
186	
187			public void paintComponent(Graphics g) {
188				if (graphImage != null) {
189					g.drawImage(graphImage, 0, 0, null);
190				}
191			}
192	
193	
194			private void updateGraphLine(Graphics graphics, FieldEnvironment field, FieldStats stats, Class<?> animalClass,
195					int index, int width, int height) {
196				int count = stats.getPopulationCount(field, animalClass);
197				int y = scalePopulationToY(height, count);
198				graphics.setColor(LIGHT_GRAY);
199				graphics.drawLine(width - 2, y, width - 2, height);
200				graphics.setColor(colors.get(animalClass));
201				graphics.drawLine(width - 3, lastVal[index], width - 2, y);
202				lastVal[index] = y;
203			}
204	
205	
206			private int scalePopulationToY(int height, int count) {
207				int y = height - ((height * count) / yMax) - 1;
208				while (y < 0) {
209					scaleDown();
210					y = height - ((height * count) / yMax) - 1;
211				}
212				return y;
213			}
