 1	import java.util.LinkedHashMap;
 2	import java.util.Map;
 3	import java.util.stream.Collectors;
 4	
 5	
 6	public class FieldStats {
 7	
 8		private final Map<Class<?>, Long> counters;
 9	
10		private boolean countsValid;
11	
12	
13		public FieldStats() {
14			counters = new LinkedHashMap<>();
15			countsValid = true;
16		}
17	
18	
19		public String getPopulationDetails(FieldEnvironment field) {
20			if (!countsValid) {
21				generateCounts(field);
22			}
23			return counters.entrySet().stream()
24					.map(entry -> entry.getKey().getName() + ": " + entry.getValue())
25					.collect(Collectors.joining(" "));
26		}
27	
28	
29		public void reset() {
30			countsValid = false;
31			counters.clear();
32		}
33	
34	
35		public void incrementCount(Class<?> animalClass) {
36			counters.merge(animalClass, 1L, Long::sum);
37		}
38	
39	
40		public void countFinished() {
41			countsValid = true;
42		}
43	
44	
45		public boolean isViable(FieldEnvironment field) {
46			if (!countsValid) {
47				generateCounts(field);
48			}
49			return counters.values().stream()
50					.filter(count -> count > 0)
51					.count() > 1;
52		}
53	
54	
55		private void generateCounts(FieldEnvironment field) {
56			reset();
57			counters.putAll(field.streamAnimals()
58					.collect(Collectors.groupingBy(Animal::getClass, LinkedHashMap::new, Collectors.counting())));
59			countsValid = true;
60		}
61	
62	
63		public int getPopulationCount(FieldEnvironment field, Class<?> key) {
64			if (!countsValid) {
65				generateCounts(field);
66			}
67			return counters.getOrDefault(key, 0L).intValue();
68		}
69	}

