  6	
  7	public class Simulator {
  8	
  9	
 10		private static final int DEFAULT_WIDTH = 320;
 11	
 12		private static final int DEFAULT_DEPTH = 200;
 13	
 14		private static final TimeCycle DEFAULT_TIMECYCLE = TimeCycle.DAY;
 15	
 16		private static final Weather DEFAULT_WEATHER = Weather.SUN;
 17	
 18		private static final int TIMECYCLE_LENGTH = 4;
 19	
 20	
 21		private List<Animal> animals;
 22	
 23		private List<Plant> plants;
 24	
 25		private FieldEnvironment field;
 26	
 27		private int step;
 28	
 29		private SimulatorView gridView;
 30	
 31		private GraphView graphView;
 32	
 33		private TimeCycle currentTimeCycle;
 34	
 35		private Climate climate;
 36	
 37		private FieldPopulator fieldPopulator;
 38	
 39		private int sickPercentage;
 40	
 41	
 42		public Simulator() {
 43			this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 44			currentTimeCycle = DEFAULT_TIMECYCLE;
 45		}
 46	
 47	
 48		public Simulator(int depth, int width) {
 49			if (width <= 0 || depth <= 0) {
 50				System.out.println("The dimensions must be greater than zero.");
 51				System.out.println("Using default values.");
 52				depth = DEFAULT_DEPTH;
 53				width = DEFAULT_WIDTH;
 54			}
 55	
 56	
 57			animals = new ArrayList<>();
 58	
 59			plants = new ArrayList<>();
 60			field = new Field(depth, width);
 61			climate = new Climate(DEFAULT_WEATHER);
 62	
 63	
 64			gridView = new SimulatorView(depth, width);
 65	
 66	
 67			graphView = new GraphView(1000, 500, 500);
 68			fieldPopulator = new FieldPopulator(graphView, climate);
 69	
 70	
 71			reset();
 72		}
 73	
 74	
 75		public void runLongSimulation() {
 76			simulate(4000);
 77		}
 78	
 79	
 80		public void simulate(int numSteps) {
 81			for (int step = 1; step <= numSteps && gridView.isViable(field); step++) {
 82				simulateOneStep();
 83				delay(60);
 84			}
 85		}
 86	
 87	
 88		public void simulateOneStep() {
 89			step++;
 90			climate.updateClimate(step);
 91	
 92			plants.forEach(plant -> plant.increaseStage(climate));
 93	
 94	
 95			List<Animal> newAnimals = new ArrayList<>();
 96			animals.forEach(animal -> animal.act(newAnimals, currentTimeCycle));
 97			animals = Stream.concat(
 98					animals.stream().filter(Animal::isAlive),
 99					newAnimals.stream())
100					.collect(Collectors.toCollection(ArrayList::new));
101	
102	
103			if (step % TIMECYCLE_LENGTH == 0) {
104				currentTimeCycle = currentTimeCycle.toggle();
105			}
106	
107			updateViews();
108		}
109	
110	
111		public void reset() {
112			step = 0;
113			fieldPopulator.populate(field, animals, plants);
114			currentTimeCycle = DEFAULT_TIMECYCLE;
115			climate.setCurrentWeather(Weather.SUN);
116	
117			sickPercentage = 0;
118			graphView.reset();
119			updateViews();
120		}
121	
122	
123		private void updateViews() {
124			sickPercentage = calculateSickPercentage();
125			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
126			graphView.showStatus(step, field);
127		}
128	
129	
130		private int calculateSickPercentage() {
131			if (animals.isEmpty()) {
132				return 0;
133			}
134	
135			long sickAnimals = animals.stream()
136					.filter(Animal::isSick)
137					.count();
138			return (int) ((sickAnimals * 100) / animals.size());
139		}
140	
141	
142		private void delay(int millisec) {
143			try {
144				Thread.sleep(millisec);
145			} catch (InterruptedException ie) {
146	
147			}
148		}
149	}

