 88					.filter(next -> getAnimalAt(next) == null)
 89					.collect(Collectors.toCollection(ArrayList::new));
 90		}
 91	
 92	
 93		@Override
 94		public Location freeAnimalAdjacentLocation(Location location) {
 95	
 96			List<Location> free = getFreeAnimalAdjacentLocations(location);
 97			if (!free.isEmpty()) {
 98				return free.get(0);
 99			} else {
100				return null;
101			}
102		}
103	
104	
105		@Override
106		public List<Location> getAdjacentAnimalLocations(Location location) {
107			assert location != null : "Null location passed to getAdjacentAnimalLocations";
108	
109			if (location == null) {
110				return Collections.emptyList();
111			}
112	
113			int row = location.getRow();
114			int col = location.getCol();
115			List<Location> locations = IntStream.rangeClosed(Math.max(0, row - 1), Math.min(depth - 1, row + 1))
116					.boxed()
117					.flatMap(nextRow -> IntStream.rangeClosed(Math.max(0, col - 1), Math.min(width - 1, col + 1))
118							.filter(nextCol -> nextRow != row || nextCol != col)
119							.mapToObj(nextCol -> new Location(nextRow, nextCol)))
120					.collect(Collectors.toCollection(ArrayList::new));
121			RANDOM.shuffle(locations);
122			return locations;
123		}
124	
125	
126		@Override
127		public int getDepth() {
128			return depth;
129		}
130	
131	
132		@Override
133		public int getWidth() {
134			return width;
135		}
136	}

