 3	
 4	public abstract class Predator extends Animal {
 5	
 6	
 7		private static final RandomService RANDOM = RandomService.shared();
 8	
 9		public Predator(boolean randomAge, FieldEnvironment field, Location location, AnimalSpecies species) {
10			super(field, location, species);
11			if (randomAge) {
12				setAge(RANDOM.nextInt(getSpecies().getMaxAge()));
13				setFoodLevel(RANDOM.nextInt(5));
14			} else {
15				setAge(0);
16				setFoodLevel(6);
17			}
18		}
19	
20	
21		protected void normalAct(List<Animal> newAnimals) {
22			giveBirth(newAnimals);
23	
24			Location newLocation = findFood();
25			if (isAlive()) {
26				if (newLocation == null) {
27					newLocation = getField().freeAnimalAdjacentLocation(getLocation());
28				}
29				moveTo(newLocation);
30			}
31		}
32	
33	
34		private Location findFood() {
35			return getField().getAdjacentAnimalLocations(getLocation()).stream()
36					.filter(this::canEatAt)
37					.findFirst()
38					.map(this::eatAnimalAt)
39					.orElse(null);
40		}
41	
42	
43		private boolean canEatAt(Location location) {
44			Animal nearAnimal = getField().getAnimalAt(location);
45			return nearAnimal != null && nearAnimal.isAlive()
46					&& (nearAnimal.getFoodChainLevel() < getFoodChainLevel() || canEatSameSpecies(nearAnimal));
47		}
48	
49	
50		private boolean canEatSameSpecies(Animal nearAnimal) {
51			return getSpecies().isCannibal()
52					&& nearAnimal.getFoodChainLevel() == getFoodChainLevel()
53					&& getFoodLevel() < 2
54					&& nearAnimal.getClass().equals(getClass());
55		}
56	
57	
58		private Location eatAnimalAt(Location location) {
59			Animal nearAnimal = getField().getAnimalAt(location);
60			nearAnimal.setDead();
61			setFoodLevel(nearAnimal.getFoodValue() + getSpecies().getAdditionalFoodValue());
62			return location;
63		}
64	}
